MAPS = json.loads(gzip.decompress(base64.b85decode(_MAPS_BLOB)))

_TEST_IDS = MAPS["test_ids"]


class Selector:
    def __init__(self):
        self.symbols = MAPS["ast_symbols"]
        self.importers = MAPS["importers"]
        self.dialect_map = MAPS["dialect_map"]
        self.attr_readers = MAPS["attr_readers"]
        self.name_usage = MAPS["name_usage"]
        self.docspans = MAPS["docspans"]
        self.monsters = set(MAPS["monsters"])
        self.func_tests = {k: {_TEST_IDS[i] for i in v} for k, v in MAPS["func_tests"].items()}
        self.module_tests = {k: {_TEST_IDS[i] for i in v} for k, v in MAPS["module_tests"].items()}
        self.pool_child = MAPS["pool_child"]
        self.pool_ids = {_TEST_IDS[i] for i in MAPS["pool_ids"]}
        self.fixture_map = MAPS["fixture_map"]
        self.callers = {}
        for caller, callees in MAPS["callgraph_edges"].items():
            for callee in callees:
                self.callers.setdefault(callee, set()).add(caller)
        self.dialect_classes = self.dialect_map["classes"]
        self.trans_imp = {}
        self._file_tests = {}

    def trans(self, mod):
        if mod in self.trans_imp:
            return self.trans_imp[mod]
        seen, stack = set(), [mod]
        while stack:
            for imp in self.importers.get(stack.pop(), []):
                if imp not in seen:
                    seen.add(imp)
                    stack.append(imp)
        self.trans_imp[mod] = seen
        return seen

    # ---------- patch parsing (hardened) ----------

    def parse_diff(self, text):
        files = {}
        cur_new, cur_old, hunk = None, None, None
        for line in text.splitlines():
            if line.startswith("+++ "):
                p = line[4:]
                cur_new = p[2:] if p.startswith("b/") else p
                if cur_new == "/dev/null":
                    cur_new = None
                files.setdefault(("new" if cur_new else "del", cur_new or cur_old), [])
                hunk = None
            elif line.startswith("--- "):
                p = line[4:]
                cur_old = p[2:] if p.startswith("a/") else p
            elif line.startswith("@@ ") and cur_new:
                m = re.match(r"@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@", line)
                hunk = {"old_start": int(m.group(1)), "lines": []}
                files[("new", cur_new)].append(hunk)
            elif hunk is not None and line[:1] in (" ", "+", "-"):
                hunk["lines"].append((line[0], line[1:]))
        return files

    @staticmethod
    def hunk_old_range(hunk):
        changed, oldno = [], hunk["old_start"]
        for t, _ in hunk["lines"]:
            if t == " ":
                oldno += 1
            elif t == "-":
                changed.append(oldno)
                oldno += 1
        if not changed:
            return hunk["old_start"] - 1, hunk["old_start"]
        return min(changed), max(changed)

    @staticmethod
    def hunk_comment_only(hunk):
        adds = [l for t, l in hunk["lines"] if t == "+"]
        dels = [t for t, _ in hunk["lines"] if t == "-"]
        if dels or not adds:
            return False
        ok = lambda s: (not s.strip()) or s.lstrip().startswith("#")
        return all(ok(l) for l in adds)

    @staticmethod
    def hunk_changed_attr(hunk):
        dels = [l for t, l in hunk["lines"] if t == "-"]
        if len(dels) != 1:
            return None
        line = dels[0].strip()
        if "=" not in line or line.startswith(("!", "<", ">", "-")):
            return None
        if line.endswith(",") or line.endswith(")"):
            return None
        target = line.split("=", 1)[0].strip()
        return target if target.isidentifier() else None

    def hunk_string_only(self, mod, hunk):
        dels = [l for t, l in hunk["lines"] if t == "-"]
        if not dels:
            return False
        lo, hi = self.hunk_old_range(hunk)
        return any(s <= lo and hi <= e for s, e in self.docspans.get(mod, []))

    def enclosing(self, mod, lo, hi):
        entries = self.symbols.get(mod, [])
        hits = [s for s in entries if not (s["e"] < lo or s["s"] > hi)]
        func_covered = set()
        for s in hits:
            if s["k"] == "function":
                func_covered.update(range(max(s["s"], lo), min(s["e"], hi) + 1))
        module_lines = [ln for ln in range(lo, hi + 1) if ln not in func_covered]
        return ([s for s in hits if s["k"] == "function"],
                [s for s in hits if s["k"] == "class"], module_lines)

    def caller_closure(self, mod, qn, depth=1):
        seen, frontier = set(), [f"{mod}:{qn}"]
        for _ in range(depth):
            nxt = []
            for q in frontier:
                for c in self.callers.get(q, ()):
                    if c not in seen:
                        seen.add(c)
                        nxt.append(c)
            frontier = nxt
            if not frontier:
                break
        return seen

    def dialect_files_tests(self, mod):
        classes = self.dialect_classes
        own = [c for c, m in classes.items() if m == mod]
        tids = set()
        for c in own:
            tids.update(self._file_tests.get(f"tests/dialects/test_{c.lower()}.py", ()))
        tids.update(self._file_tests.get("tests/dialects/test_dialect.py", ()))
        seen, frontier = set(), list(own)
        while frontier:
            nxt = []
            for child, parent in self.dialect_map["edges"]:
                if parent in frontier and child not in seen:
                    seen.add(child)
                    nxt.append(child)
            frontier = nxt
        for c in seen:
            cm = classes.get(c)
            if cm:
                tids.update(self._file_tests.get(f"tests/dialects/test_{c.lower()}.py", ()))
        return tids

    def is_dialect_module(self, mod):
        return mod in self.dialect_classes.values()

    def select(self, patch_text, tests_meta):
        all_ids = {t["id"] for t in tests_meta}
        self._file_tests = {}
        for t in tests_meta:
            self._file_tests.setdefault(t["file"], set()).add(t["id"])
        files = self.parse_diff(patch_text)
        if not files:
            return set(all_ids)
        tids = set()
        for (kind, path), hunks in files.items():
            if kind == "del":
                return set(all_ids)
            if path.startswith("tests/fixtures/"):
                rel = path[len("tests/fixtures/"):]
                mapped = self.fixture_map.get(rel)
                if mapped is None:
                    return set(all_ids)
                for x in mapped:
                    if "::" in x:
                        tids.add(x)
                    else:
                        tids.update(self._file_tests.get(x, ()))
                continue
            if path.startswith("tests/"):
                if path.endswith(("conftest.py", "__init__.py", "leakcheck.py")):
                    return set(all_ids)
                tids.update(self._file_tests.get(path, ()))
                if not re.search(r"(^|/)test_\w+\.py$", path):
                    return set(all_ids)
                continue
            if path.startswith("sqlglot/"):
                if not path.endswith(".py"):
                    return set(all_ids)
                mod = path[:-3].replace("/", ".")
                if mod not in self.symbols:
                    return set(all_ids)
                code_hunks = [h for h in hunks if not self.hunk_comment_only(h)]
                if not code_hunks:
                    continue
                if all(self.hunk_string_only(mod, h) for h in code_hunks):
                    continue
                broad = False
                for h in code_hunks:
                    if self.hunk_string_only(mod, h):
                        continue
                    lo, hi = self.hunk_old_range(h)
                    funcs, classes, mlines = self.enclosing(mod, lo, hi)
                    if mlines and classes and not funcs and self.is_dialect_module(mod):
                        attr = self.hunk_changed_attr(h)
                        if attr:
                            tids |= self.dialect_files_tests(mod)
                            for rm, attrs in self.attr_readers.items():
                                for qn in attrs.get(attr, ()):
                                    ts = self.func_tests.get(f"{rm}:{qn}", ())
                                    if len(ts) <= 300:
                                        tids.update(ts)
                            continue
                    if mlines or classes:
                        if self.is_dialect_module(mod):
                            tids |= self.dialect_files_tests(mod)
                            tids.update(self.module_tests.get(mod, ()))
                        elif mod.startswith("sqlglot.expressions.") and classes:
                            for cl in classes:
                                users = self.name_usage.get(cl["q"], {})
                                for um, quals in users.items():
                                    for q in quals:
                                        tids.update(self.func_tests.get(f"{um}:{q}", ()))
                            tids.update(self._file_tests.get("tests/test_serde.py", ()))
                        else:
                            tids.update(self.module_tests.get(mod, ()))
                            for imp in self.trans(mod):
                                tids.update(self.module_tests.get(imp, ()))
                            broad = True
                        continue
                    for fn in funcs:
                        key = f"{mod}:{fn['q']}"
                        tids.update(self.func_tests.get(key, ()))
                        for c in self.caller_closure(mod, fn["q"], 1):
                            tids.update(self.func_tests.get(c, ()))
                if broad:
                    tids -= self.monsters
                for t, info in self.pool_child.items():
                    mods = set(info.get("modules", []))
                    if mod not in mods:
                        continue
                    touched = False
                    for h in code_hunks:
                        if self.hunk_string_only(mod, h):
                            continue
                        lo, hi = self.hunk_old_range(h)
                        mlines = info.get("module_lines", {}).get(mod, [])
                        if any(lo - 2 <= ln <= hi + 2 for ln in mlines):
                            touched = True
                            break
                        fns, cls, ml = self.enclosing(mod, lo, hi)
                        for fn in fns:
                            if f"{mod}:{fn['q']}" in set(info.get("funcs", [])):
                                touched = True
                                break
                    if touched:
                        tids.add(t)
                continue
            if path.endswith((".md", ".rst", ".txt", ".yml", ".yaml")):
                continue
            return set(all_ids)
        return {t for t in tids if t in all_ids}


def split_optimal(nums, sec):
    items = sorted(set(nums), key=lambda n: sec.get(n, 0), reverse=True)
    if not items:
        return []
    best = None
    for k in range(1, min(MAX_WORKERS, len(items)) + 1):
        loads = [0.0] * k
        for n in items:
            i = min(range(k), key=lambda j: loads[j])
            loads[i] += sec.get(n, 0)
        c = max(loads) + WORKER_COST * k
        if best is None or c < best[0]:
            best = (c, k)
    k = best[1]
    workers = [[] for _ in range(k)]
    loads = [0.0] * k
    for n in items:
        i = min(range(k), key=lambda j: loads[j])
        workers[i].append(n)
        loads[i] += sec.get(n, 0)
    return workers


def main():
    data = Path(sys.argv[1]) if len(sys.argv) > 1 else DATA
    meta = json.loads((data / "tests.json").read_text())["tests"]
    i2n = {t["id"]: t["number"] for t in meta}
    sec = {t["number"]: t["seconds"] for t in meta}
    sel = Selector()
    for pf in sorted((data / "commits").glob("*.patch")):
        try:
            tids = sel.select(pf.read_text(errors="replace"), meta)
            nums = {i2n[t] for t in tids if t in i2n}
            workers = split_optimal(nums, sec)
        except Exception:
            traceback.print_exc()
            workers = split_optimal(set(i2n.values()), sec)
        print(json.dumps({"commit": pf.stem, "workers": workers}))


if __name__ == "__main__":
    main()
